import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { renderer, scene, camera } from './renderer';
import { pScale } from './shared';
import { clamp, smooth } from '../common/math';
import { CONFIG } from '../config';

/* Bloom chỉ dùng khi trời tối: ban ngày vẫn vẽ thẳng như trước (không tốn thêm) */
export const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
export const bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0, 0.4, 0.98);
composer.addPass(bloomPass);
composer.addPass(new OutputPass());

/* scale: tỉ lệ độ phân giải bloom so với màn hình (bậc chất lượng, D-018); 0 = tắt bloom, đêm vẽ thẳng như ban ngày */
export const bloomState = { scale: 1 };
export function renderFrame(night: number, dt: number) {
  const bloomK = smooth(clamp((night - 0.05) / 0.6, 0, 1));
  if (bloomK > 0.001 && bloomState.scale > 0) { bloomPass.strength = 0.6 * bloomK; composer.render(dt); }
  else renderer.render(scene, camera);
}

/* Đổi pixelRatio (bậc chất lượng): cấp lại canvas + framebuffer composer một lần */
export function setPixelRatio(r: number) {
  if (Math.abs(renderer.getPixelRatio() - r) < 1e-3) return;
  renderer.setPixelRatio(r); onResize();
}

/* Gộp các sự kiện resize / orientationchange liên tiếp (xoay máy bắn nhiều lần) thành một onResize(), sau resizeDebounceMs kể từ sự kiện cuối */
let resizeTimer = 0;
export function scheduleResize() {
  clearTimeout(resizeTimer);
  resizeTimer = window.setTimeout(() => requestAnimationFrame(onResize), CONFIG.ui.resizeDebounceMs);
}

export function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setPixelRatio(renderer.getPixelRatio()); composer.setSize(window.innerWidth, window.innerHeight);
  if (bloomState.scale > 0 && bloomState.scale < 1) { const pr = renderer.getPixelRatio() * bloomState.scale; bloomPass.setSize(window.innerWidth * pr, window.innerHeight * pr); }
  const h = renderer.getDrawingBufferSize(new THREE.Vector2()).y;
  pScale.value = h / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
}
/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
import * as THREE from 'three';
import { scene, camera, controls } from '../core/renderer';
import { cam, keys } from '../views/state';
import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
import { exBuildGlider, exPlaceGlider } from './glider';
import { exChase } from './chase';
import { exShowChooser } from './chooser';

const _inp: GliderInput = { turn: 0, climb: 0 };   // đầu vào tái dùng mỗi khung

let glider: THREE.Group | null = null;
let state: GliderState | null = null;

const active = () => cam.mode === 'glider' && state !== null;

/* Một bước: mô phỏng, đặt dù, đặt camera bám */
function advance(dt: number, inp: GliderInput): void {
  exStep(state!, inp, dt);
  exPlaceGlider(glider!, state!);
  exChase(camera, controls.target, state!, dt);
}

export const explore = {
  active,
  get state() { return state; },
  get glider() { return glider; },
  start(): void {
    state = exCreate();
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    document.body.classList.add('explore');
  },
  update(dt: number): void {
    if (!active()) return;
  const mesh = new THREE.Mesh(geo, mat);
  mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
  const g = new THREE.Group(); g.name = 'ex-glider'; g.add(mesh);
  return g;
}

/* Đặt dù theo trạng thái bay: quay yaw trước, rồi cuộn quanh trục bay (bank > 0: nghiêng trái, cánh trái hạ) */
export function exPlaceGlider(g: THREE.Group, s: GliderState): void {
  g.position.copy(s.pos);
  g.rotation.set(-s.bank, s.yaw, 0, 'YXZ');
  const m = (g.children[0] as THREE.Mesh).material as THREE.MeshStandardMaterial;
  m.emissiveIntensity = shared.uNight.value;
}

